// ChatService — gRPC façade for the control-plane chatbot.
//
// The chatbot is a delegator, not an executor. It plans, suggests, coordinates,
// and orchestrates — but always delegates execution to agents. Forced tool
// calling is mandatory: even user-facing responses are emitted as tool calls.
//
// threetched owns LLM provider/model routing (OD-28). SendRequest carries
// the provider/model selection from threetched's state; the server does not
// make routing decisions.
//
// Wire vocabulary mirrors AI SDK UIMessage part kinds so renderers stay
// portable, but the producer is our own runtime — no AI SDK provider library.

syntax = "proto3";

package op_chat.chat;

// ============================================================================
// CHAT SERVICE
// ============================================================================

service ChatService {
  // Stream a chat completion. Returns a stream of ChatFrame events.
  // The chatbot delegates to agents via forced tool calls; it never executes
  // backplane operations directly.
  rpc Send(SendRequest) returns (stream ChatFrame);

  // Approve a tool call that requires operator confirmation.
  // The chatbot is a delegator — approval gates agent delegation, not direct
  // execution.
  rpc Approve(ApproveRequest) returns (ApproveResponse);

  // Cancel an in-flight chat stream.
  rpc Cancel(CancelRequest) returns (CancelResponse);
}

